import { createQueryUtils } from '@wix/sdk-runtime/query-builder-utils'
import type {
  QueryBuilder as SDKQueryBuilder,
  FilterFactory,
  SortFactory,
} from '@wix/sdk-types'
import { WixDataQueryRequest, WixDataQuerySpec, WixDataItem } from './types'

// Create the base query utilities from SDK runtime
const baseQueryUtils = createQueryUtils<
  WixDataItem,
  WixDataQuerySpec,
  WixDataQueryRequest
>({ transformSystemFields: false })

/**
 * WixData QueryBuilder type.
 * @internal
 */
export type WixDataQueryBuilder = SDKQueryBuilder<
  WixDataItem,
  WixDataQuerySpec,
  WixDataQueryRequest
>

/**
 * Creates a new query builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Build a query"
 * import { items, QueryBuilder, Filter, Sort } from '@wix/data'
 *
 * const request = QueryBuilder()
 *   .withFilter(
 *     Filter.and(
 *       Filter('status').eq('active'),
 *       Filter('age').gt(25)
 *     )
 *   )
 *   .withSorting(Sort('lastName').asc())
 *   .withPaging({ limit: 10, offset: 0 })
 *   .build()
 *
 * const result = await items.query<MyItem>('myCollection', request)
 * ```
 */
export const QueryBuilder: () => WixDataQueryBuilder =
  baseQueryUtils.QueryBuilder

/**
 * Filter factory for creating filter expressions.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create filter expressions"
 * import { Filter } from '@wix/data'
 *
 * // Simple field filter
 * Filter('status').eq('active')
 *
 * // Combining filters with AND
 * Filter.and(
 *   Filter('orderId').eq('123'),
 *   Filter('amount').gt(100)
 * )
 *
 * // Combining filters with OR
 * Filter.or(
 *   Filter('status').eq('pending'),
 *   Filter('status').eq('active')
 * )
 *
 * // Negating a filter
 * Filter.not(Filter('status').eq('deleted'))
 * ```
 */
export const Filter: FilterFactory<WixDataItem, WixDataQuerySpec> =
  baseQueryUtils.Filter

/**
 * Sort factory for creating sort expressions.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create sort expressions"
 * import { Sort, QueryBuilder } from '@wix/data'
 *
 * // Descending sort
 * Sort('amount').desc()
 *
 * // Ascending sort
 * Sort('name').asc()
 *
 * // Use with QueryBuilder
 * QueryBuilder()
 *   .withSorting(Sort('amount').desc(), Sort('name').asc())
 *   .build()
 * ```
 */
export const Sort: SortFactory<WixDataQuerySpec> = baseQueryUtils.Sort

// Re-export types for convenience
export type {
  FilterExpression,
  SortExpression,
  PagingFor,
} from '@wix/sdk-types'
